113	/**
114	 * Returns true if the event is a SDK-injected `user.message` that should not
115	 * be shown to the user (e.g. skill-content injection).
116	 *
117	 * The SDK marks these via a non-`'user'` `source` field. Older sessions
118	 * persisted before `source` existed will not be filtered; that is accepted
119	 * leakage rather than guessed-at content sniffing.
120	 */
121	function isSyntheticUserMessage(event: ISessionEvent): boolean {
122		if (event.type !== 'user.message') {
123			return false;
124		}
125		const source = (event as ISessionEventMessage).data?.source;
126		return !!source && source.toLowerCase() !== 'user';
127	}
